<?php
require __DIR__.'/../config/app.php';
$me=require_role('admin');$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    csrf_check();$action=$_POST['action']??'publish';
    if($action==='delete_announcement'){
        try{db()->prepare('DELETE FROM announcements WHERE id=?')->execute([(int)($_POST['id']??0)]);flash('Announcement deleted. Previously delivered notifications remain in student inboxes.');}
        catch(Throwable $t){flash('Could not delete announcement.','error');}
        go('admin/announcements.php');
    }
    if($action==='save_announcement'){
        $id=(int)($_POST['id']??0);$title=trim((string)($_POST['title']??''));$body=trim((string)($_POST['body']??''));
        if($id<1||$title===''||mb_strlen($title)>190||$body==='')$error='Enter a valid title and message.';
        else{try{db()->prepare('UPDATE announcements SET title=?,body=? WHERE id=?')->execute([$title,$body,$id]);flash('Announcement updated. Previously delivered notifications remain unchanged.');go('admin/announcements.php');}catch(Throwable $t){$error='Could not update the announcement.';}}
    }
    if($action==='read_all'){
        try{db()->prepare('UPDATE notifications SET is_read=1 WHERE user_id=? AND is_read=0')->execute([$me['id']]);flash('All notifications marked as read.');}
        catch(Throwable $t){flash('Could not update notifications.','error');}
        go('admin/announcements.php');
    }
    if($action==='read'){
        try{db()->prepare('UPDATE notifications SET is_read=1 WHERE id=? AND user_id=?')->execute([(int)($_POST['id']??0),$me['id']]);flash('Notification marked as read.');}
        catch(Throwable $t){flash('Could not update notification.','error');}
        go('admin/announcements.php');
    }
    if($action==='delete'){
        try{$q=db()->prepare('DELETE FROM notifications WHERE id=? AND user_id=?');$q->execute([(int)($_POST['id']??0),$me['id']]);flash($q->rowCount()?'Notification deleted.':'Notification not found.');}
        catch(Throwable $t){flash('Could not delete notification.','error');}
        go('admin/announcements.php');
    }
    $title=trim((string)($_POST['title']??''));$body=trim((string)($_POST['body']??''));
    if($title===''||$body==='')$error='Enter both a title and message.';
    else{
        try{$pdo=db();$pdo->beginTransaction();$q=$pdo->prepare('INSERT INTO announcements(title,body,created_by) VALUES(?,?,?)');$q->execute([$title,$body,$me['id']]);$notify=$pdo->prepare("INSERT INTO notifications(user_id,title,message) SELECT u.id,'New announcement',? FROM users u WHERE u.role='student' AND u.is_active=1 AND COALESCE((SELECT in_app_notifications FROM user_settings s WHERE s.user_id=u.id),1)=1");$notify->execute([$title]);$pdo->commit();flash('Announcement published to students.');go('admin/announcements.php');}
        catch(Throwable $t){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();$error='Could not publish announcement.';}
    }
}
$announcementSearch=trim((string)($_GET['q']??''));$announcements=[];$notifications=[];$unreadCount=0;$editAnnouncement=null;
try{$q=db()->prepare('SELECT id,title,body,created_at FROM announcements WHERE (?=\'\' OR title LIKE ? OR body LIKE ?) ORDER BY created_at DESC');$term='%'.$announcementSearch.'%';$q->execute([$announcementSearch,$term,$term]);$announcements=$q->fetchAll();if(isset($_GET['edit'])){$q=db()->prepare('SELECT id,title,body FROM announcements WHERE id=?');$q->execute([(int)$_GET['edit']]);$editAnnouncement=$q->fetch()?:null;}$q=db()->prepare('SELECT id,title,message,is_read,created_at FROM notifications WHERE user_id=? ORDER BY created_at DESC,id DESC LIMIT 10');$q->execute([$me['id']]);$notifications=$q->fetchAll();$q=db()->prepare('SELECT COUNT(*) FROM notifications WHERE user_id=? AND is_read=0');$q->execute([$me['id']]);$unreadCount=(int)$q->fetchColumn();}catch(Throwable $t){}
if(($_GET['export']??'')==='csv'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="eventhub-announcements-'.date('Ymd').'.csv"');$out=fopen('php://output','w');fputcsv($out,['Title','Message','Published']);foreach($announcements as $r)fputcsv($out,[$r['title'],$r['body'],$r['created_at']]);fclose($out);exit;}
$perPage=25;$totalRecords=count($announcements);$totalPages=(int)ceil($totalRecords/$perPage);$currentPage=max(1,min($totalPages?:1,(int)($_GET['page']??1)));$announcements=array_slice($announcements,($currentPage-1)*$perPage,$perPage);$pageTitle='Notifications';$bodyClass='dashboard-page admin-page';$activePage='settings';$adminSection='settings';require __DIR__.'/../includes/header.php';
?><div class="dash-layout admin-layout"><?php require __DIR__.'/../includes/sidebar.php';?><main class="content-page admin-content admin-events-page"><header class="admin-page-heading"><div><span class="admin-eyebrow">CAMPUS UPDATES</span><h1>Notifications</h1><p>Publish announcements and manage your admin notifications.</p></div></header><?php require __DIR__.'/section-nav.php';?><?php if($error):?><div class="inline-error"><?=e($error)?></div><?php endif;?>
<section class="admin-work-card"><div class="admin-card-heading"><span class="admin-heading-icon"><?=eventhub_icon('megaphone')?></span><div><h2>New announcement</h2><p>Students with in-app notifications enabled will receive it.</p></div></div><form class="form-card admin-event-form" method="post"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="publish"><label>Title<input required maxlength="190" name="title" placeholder="Announcement title"></label><label>Message<textarea required rows="4" name="body" placeholder="Write your announcement..."></textarea></label><div class="admin-form-actions"><span class="profile-role">For active student accounts</span><button class="btn primary" type="submit">Publish announcement</button></div></form></section>
<?php if($editAnnouncement):?><section class="admin-work-card"><div class="admin-card-heading"><span class="admin-heading-icon"><?=eventhub_icon('clipboard')?></span><div><h2>Edit announcement</h2><p>Previously sent inbox notifications remain unchanged.</p></div></div><form class="form-card admin-event-form" method="post"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="save_announcement"><input type="hidden" name="id" value="<?=$editAnnouncement['id']?>"><label>Title<input required maxlength="190" name="title" value="<?=e($editAnnouncement['title'])?>"></label><label>Message<textarea required rows="4" name="body"><?=e($editAnnouncement['body'])?></textarea></label><div class="admin-form-actions"><a class="btn outline" href="<?=url('admin/announcements.php')?>">Cancel</a><button class="btn primary" type="submit">Save Changes</button></div></form></section><?php endif;?>
<section class="admin-work-card"><div class="admin-card-heading admin-inbox-heading"><span class="admin-heading-icon"><?=eventhub_icon('bell')?></span><div><h2>Recent notifications <span class="admin-count"><?=count($notifications)?></span></h2><p><?=$unreadCount?> unread for this admin account.</p></div><form method="post"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="read_all"><button class="btn outline" type="submit" <?=$unreadCount?'':'disabled'?>>Mark all as read</button></form></div><?php if($notifications):?><div class="notification-list admin-notification-list"><?php foreach($notifications as $notification):?><article class="notification-card <?=$notification['is_read']?'is-read':'is-unread'?>"><span class="notification-symbol"><?=eventhub_icon('bell')?></span><div class="notification-copy"><h2><?=e($notification['title'])?></h2><p><?=e($notification['message'])?></p><time><?=date('d M Y g:i A',strtotime($notification['created_at']))?></time></div><div class="notification-actions"><?php if(!(int)$notification['is_read']):?><form method="post"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="read"><input type="hidden" name="id" value="<?=$notification['id']?>"><button class="notification-read" type="submit" aria-label="Mark as read">✓</button></form><?php endif;?><form method="post" onsubmit="return confirm('Delete this notification?')"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$notification['id']?>"><button class="notification-delete" type="submit" aria-label="Delete notification" title="Delete notification">Delete</button></form></div></article><?php endforeach;?></div><?php else:?><div class="empty">No notifications for this admin account yet.</div><?php endif;?></section>
<section class="admin-work-card"><form method="get" class="admin-report-filters"><input name="q" value="<?=e($announcementSearch)?>" placeholder="Search announcements"><button class="btn primary">Search</button><a class="btn outline" href="<?=url('admin/announcements.php?'.http_build_query(['q'=>$announcementSearch,'export'=>'csv']))?>">Export CSV</a></form><div class="admin-card-heading"><span class="admin-heading-icon"><?=eventhub_icon('clipboard')?></span><div><h2>All announcements <span class="admin-count"><?=count($announcements)?></span></h2><p>Manage published announcements.</p></div></div><?php if($announcements):?><div class="admin-announcement-list"><?php foreach($announcements as $r):?><article><span class="admin-announcement-date"><?=date('d M',strtotime($r['created_at']))?></span><div><strong><?=e($r['title'])?></strong><p><?=e($r['body'])?></p><small><?=date('d M Y, g:i A',strtotime($r['created_at']))?></small><div class="admin-row-actions"><a href="<?=url('admin/announcements.php?edit='.$r['id'])?>">Edit</a><form method="post" class="inline-form" onsubmit="return confirm('Delete this announcement? Previously delivered notifications remain.')"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="delete_announcement"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="text-button" type="submit">Delete</button></form></div></div></article><?php endforeach;?></div><?php else:?><div class="empty">No announcements have been published yet.</div><?php endif;?></section><?php require __DIR__.'/../includes/admin-pagination.php';?></main></div><?php require __DIR__.'/../includes/footer.php';
